1	export type Cents = number
2	
3	export function toCents(euro: number): Cents {
4	    return Math.round(euro * 100)
5	}
6	
7	export function formatAmount(amount: Cents): string {
8	    return `${(amount / 100).toFixed(2)} EUR`
9	}
