1	const stock    = new Map<string, number>()
2	const reserved = new Map<string, number>()
3	
4	export function setStock(sku: string, quantity: number): void {
5	    stock.set(sku, quantity)
6	}
7	
8	export function available(sku: string): number {
9	    return (stock.get(sku) ?? 0) - (reserved.get(sku) ?? 0)
10	}
11	
12	export function reserve(sku: string, quantity: number): boolean {
13	    if (available(sku) < quantity)
14	        return false
15	    reserved.set(sku, (reserved.get(sku) ?? 0) + quantity)
16	    return true
17	}
18	
19	export function release(sku: string, quantity: number): void {
20	    const current = reserved.get(sku) ?? 0
21	    reserved.set(sku, Math.max(0, current - quantity))
22	}
23	
24	/*  units that came back from a customer are on the shelf again  */
25	export function restock(sku: string, quantity: number): void {
26	    stock.set(sku, (stock.get(sku) ?? 0) + quantity)
27	}
28

1	import type { Order } from "./order"
2	
3	const orders = new Map<string, Order>()
4	
5	/*  the store keeps its own record, so later changes to the caller's object stay out of it  */
6	function toRecord(order: Order): Order {
7	    return {
8	        id:          order.id,
9	        customer:    { ...order.customer },
10	        items:       order.items.map((item) => ({ ...item })),
11	        subtotal:    order.subtotal,
12	        total:       order.total,
13	        tags:        [...order.tags],
14	        status:      order.status,
15	        placedOn:    order.placedOn,
16	        deliveredOn: order.deliveredOn
17	    }
18	}
19	
20	/*  store a new order and hand back the stored record  */
21	export async function saveOrder(order: Order): Promise<Order> {
22	    if (orders.has(order.id))
23	        throw new Error(`order ${order.id} already exists`)
24	    const record = toRecord(order)
25	    orders.set(order.id, record)
26	    return record
27	}
28	
29	export async function loadOrder(id: string): Promise<Order | undefined> {
30	    return orders.get(id)
31	}
32	
33	export async function ordersOf(customerId: string): Promise<Order[]> {
34	    return [...orders.values()].filter((o) => o.customer.id === customerId)
35	}
36	
37	export async function allOrders(): Promise<Order[]> {
38	    return [...orders.values()]
39	}
