67	/*  what is paid back for the lines of a return  */
68	export function returnAmount(order: Order, lines: ReturnLine[]): Cents {
69	    let amount = 0
70	    for (const line of lines) {
71	        const item = orderedItem(order, line)
72	        amount += Math.round(toCents(item.unitPrice) * line.quantity * order.total / order.subtotal)
73	    }
74	    return amount
75	}
76	
77	/*  units of every item of an order that can still come back  */
78	export function returnableUnits(order: Order): ReturnLine[] {
79	    return order.items
80	        .map((item) => ({ sku: item.sku, quantity: item.quantity - returnedQuantity(order.id, item.sku) }))
81	        .filter((line) => line.quantity > 0)
82	}
83	
84	/*  one text line per return of an order, for the account page  */
85	export function returnSummary(orderId: string): string[] {
86	    return returnsOf(orderId).map((record) => {
87	        const units = record.lines.reduce((sum, line) => sum + line.quantity, 0)
88	        return `${record.receivedOn}: units ${units}, lines ${record.lines.length}`
89	    })
90	}
91	
92	function restockLines(lines: ReturnLine[]): void {
93	    for (let i = 1; i < lines.length; i++)
94	        restock(lines[i].sku, lines[i].quantity)
95	}

